  rel=Path(name)
  if rel.is_absolute() or '..' in rel.parts or ':' in name:raise ValueError('unsafe path')
  target=(root/rel).resolve()
  if not target.is_relative_to(root) or target in seen:raise ValueError('duplicate or escaped path')
  seen.add(target)
  if type(size)is not int or size<0 or not isinstance(digest,str) or not re.fullmatch('[0-9a-f]{64}',digest):raise ValueError('invalid manifest')
  reasons=[]
  if not target.is_file():reasons.append('missing')
  else:
   raw=target.read_bytes()
   if len(raw)!=size:reasons.append('size')
   if hashlib.sha256(raw).hexdigest()!=digest:reasons.append('sha256')
  if reasons:out.append({'path':name,'errors':reasons})
 return sorted(out,key=lambda x:x['path'])

